function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50) return 's needs 1 to 50 characters.';
  if (!/^[01]+$/.test(s)) return "s may only contain '0' and '1'.";
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and the length of s.';
  return null;
}

