function countKConstraintSubstrings(s, k) {
  let left = 0;
  let zeros = 0;
  let ones = 0;
  let count = 0;
  for (let right = 0; right < s.length; right++) {
    if (s[right] === '0') {
      zeros++;
    } else {
      ones++;
    }
    while (zeros > k && ones > k) {
      if (s[left] === '0') {
        zeros--;
      } else {
        ones--;
      }
      left++;
    }
    count += right - left + 1;
  }
  return count;
}

