function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(40, 50) : int(1, 9);
  // Vary the share of ones so some strings are lopsided and others balanced.
  const bias = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < bias ? '1' : '0';
  const k = rand() < 0.6 ? int(1, Math.min(n, 3)) : int(1, n);
  return [s, k];
}
